const EXPECTED_TZ = 'America/New_York';
const wfTz = $workflow.settings?.timezone || $getWorkflowStaticData('global').timezone || EXPECTED_TZ;
// n8n exposes workflow timezone via settings; also assert GENERIC_TIMEZONE indirectly via explicit var
const tz = String($vars.STRUCTURE_ALERT_TIMEZONE || wfTz || EXPECTED_TZ);
if (tz !== EXPECTED_TZ) {
  throw Object.assign(new Error(`timezone mismatch: expected ${EXPECTED_TZ}, got ${tz}`), { step: 'timezone' });
}
const tickers = String($vars.STRUCTURE_ALERT_TICKERS || 'SPY').split(/[,\s]+/).filter(Boolean);
const channel = $vars.SLACK_ALERT_CHANNEL;
const baseUrl = String($vars.MASSIVE_BASE_URL || 'https://api.massive.com').replace(/\/$/, '');
const healthUrl = String($vars.HEALTHCHECK_URL || '').replace(/\/$/, '');
if (!healthUrl) throw Object.assign(new Error('HEALTHCHECK_URL missing'), { step: 'config' });
if (!channel) throw Object.assign(new Error('SLACK_ALERT_CHANNEL missing'), { step: 'config' });
const executionId = String($execution.id);
return [{ json: { tickers, channel, baseUrl, healthUrl, executionId, timezone: tz } }];

const cfg = $('Load Config + TZ').first().json;
const stale = $input.all().map(i => i.json).filter(r => r && r.id);
const texts = stale.map(r => `STRUCTURE ALERT FAILED - stale_sweeper: stale running row (likely crash) run_id=${r.id}`);
return [{ json: { ...cfg, staleIds: stale.map(r => r.id), staleTexts: texts } }];

const item = $input.first().json;
if (!item.staleTexts?.length) return [{ json: item }];
return item.staleTexts.map(text => ({ json: { ...item, text } }));

const auth = $input.first().json;
if (auth.ok !== true) {
  return [{ json: { ok: false, step: 'slack_preflight', error: auth.error || 'auth_test_failed', runId: $('Insert Run running').first().json.id, channel: $('Load Config + TZ').first().json.channel, healthUrl: $('Load Config + TZ').first().json.healthUrl } }];
}
const channel = $('Load Config + TZ').first().json.channel;
const isUser = /^[UW]/.test(channel);
return [{ json: { ok: true, channel, isUser, runId: $('Insert Run running').first().json.id, cfg: $('Load Config + TZ').first().json } }];

const dest = $input.first().json;
const prev = $('Check auth.test').first().json;
if (dest.ok !== true) {
  return [{ json: { ok: false, step: 'slack_preflight', error: dest.error || 'conversations_failed', runId: prev.runId, channel: prev.channel, healthUrl: prev.cfg.healthUrl } }];
}
return [{ json: { ok: true, runId: prev.runId, cfg: prev.cfg } }];

const cfg = $json.cfg;
const runId = $json.runId;
const FAILURE_PREFIX = 'STRUCTURE ALERT FAILED - ';
function redact(err, maxLen = 500) {
  let text = err == null ? 'unknown error' : (err.message || String(err));
  text = text.replace(/\b(?:xox[baprs]-|xapp-)[A-Za-z0-9-]+/g, '[REDACTED]');
  return text.replace(/\s+/g, ' ').trim().slice(0, maxLen);
}
function emaSeries(values, length) {
  const out = Array(values.length).fill(null);
  if (values.length < length) return out;
  const k = 2 / (length + 1);
  let sum = 0; for (let i = 0; i < length; i++) sum += values[i];
  let prev = sum / length; out[length - 1] = prev;
  for (let i = length; i < values.length; i++) { prev = values[i] * k + prev * (1 - k); out[i] = prev; }
  return out;
}
function atrSeries(bars, length = 14) {
  const out = Array(bars.length).fill(null);
  if (bars.length < length + 1) return out;
  const trs = bars.map((b, i) => i === 0 ? b.high - b.low : Math.max(b.high - b.low, Math.abs(b.high - bars[i-1].close), Math.abs(b.low - bars[i-1].close)));
  let atr = trs.slice(0, length).reduce((a, b) => a + b, 0) / length; out[length - 1] = atr;
  for (let i = length; i < bars.length; i++) { atr = (atr * (length - 1) + trs[i]) / length; out[i] = atr; }
  return out;
}
function msToNyDate(ms) {
  return new Intl.DateTimeFormat('en-CA', { timeZone: 'America/New_York', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(ms));
}
function formatPrice(n) { return (Math.round(n * 100) / 100).toFixed(2); }
function formatMsg(s) {
  const gaps = s.gapsAbove?.length ? s.gapsAbove.map(formatPrice).join(', ') : 'none';
  const atrPart = s.invalidationAtr == null ? 'n/a ATR' : formatPrice(s.invalidationAtr) + ' ATR';
  const five = s.fiveDayPct == null ? 'n/a' : ((s.fiveDayPct > 0 ? '+' : '') + formatPrice(s.fiveDayPct) + '%');
  const body = `*LOWER HIGH CONFIRMED: ${s.ticker}* H1 ${s.h1Date} ${formatPrice(s.h1Price)}. Retest ${s.retestDate} high ${formatPrice(s.retestHigh)}. Close ${formatPrice(s.close)}, below retest low ${formatPrice(s.retestLow)}. Invalidation: close above H1 (${formatPrice(s.invalidationAway)} away, ${atrPart}). Price ${s.priceVsEma65} EMA65, Price ${s.priceVsEma200} EMA200. 5d ${five}. Unfilled gaps above: ${gaps}. UNTESTED RULE: awareness only.`;
  const words = body.split(/\s+/); return words.length <= 120 ? body : words.slice(0, 120).join(' ');
}
function isSwingHigh(bars, i, left = 2, right = 2) {
  if (i < left || i > bars.length - 1 - right) return false;
  const h = bars[i].high;
  for (let j = i - left; j <= i + right; j++) if (j !== i && bars[j].high >= h) return false;
  return true;
}
function detect(ticker, bars) {
  if (bars.length < 220) throw Object.assign(new Error('bar count < 220 (' + bars.length + ')'), { step: 'validate_bars' });
  const closes = bars.map(b => b.close);
  const ema65 = emaSeries(closes, 65); const ema200 = emaSeries(closes, 200); const atr = atrSeries(bars, 14);
  const fiveDay = closes.length > 5 ? ((closes.at(-1) - closes.at(-6)) / closes.at(-6)) * 100 : null;
  const swingIdx = []; for (let i = 0; i < bars.length; i++) if (isSwingHigh(bars, i)) swingIdx.push(i);
  const setups = [];
  for (let s = 0; s < swingIdx.length; s++) {
    const h1i = swingIdx[s]; const h1 = bars[h1i];
    for (let r = s + 1; r < swingIdx.length; r++) {
      const ri = swingIdx[r]; const retest = bars[ri]; if (!(retest.high < h1.high)) continue;
      for (let c = ri + 1; c < bars.length; c++) {
        if (!(bars[c].close < retest.low)) continue;
        const conf = bars[c]; const away = h1.high - conf.close; const atrVal = atr[c];
        const e65 = ema65[c]; const e200 = ema200[c];
        setups.push({
          ticker: ticker.toUpperCase(), h1Date: h1.date, h1Price: h1.high, retestDate: retest.date,
          retestHigh: retest.high, retestLow: retest.low, close: conf.close, confirmDate: conf.date,
          invalidationAway: away, invalidationAtr: atrVal ? away / atrVal : null,
          priceVsEma65: e65 == null ? 'n/a' : (conf.close >= e65 ? 'above' : 'below'),
          priceVsEma200: e200 == null ? 'n/a' : (conf.close >= e200 ? 'above' : 'below'),
          fiveDayPct: fiveDay, gapsAbove: [], key: `${ticker.toUpperCase()}|${h1.date}|${retest.date}`
        });
        break;
      }
    }
  }
  const lastDate = bars.at(-1).date;
  const today = setups.filter(s => s.confirmDate === lastDate);
  return today.length ? [today.at(-1)] : [];
}

const alerts = [];
const errors = [];
for (const ticker of cfg.tickers) {
  try {
    const end = new Date(); const start = new Date(); start.setUTCDate(start.getUTCDate() - 420);
    const from = start.toISOString().slice(0, 10); const to = end.toISOString().slice(0, 10);
    // Massive API key comes from Header Auth credential on the HTTP helper below via this.helpers —
    // use credential-backed request: append apiKey from credential is not available in Code;
    // call HTTP Request node pattern: we use helpers.httpRequest with credential.
    const res = await this.helpers.httpRequestWithAuthentication.call(this, 'httpHeaderAuth', {
      method: 'GET',
      url: `${cfg.baseUrl}/v2/aggs/ticker/${encodeURIComponent(ticker)}/range/1/day/${from}/${to}?adjusted=true&sort=asc&limit=50000`,
      qs: {}
    });
    const results = res?.results;
    if (!Array.isArray(results) || !results.length) throw Object.assign(new Error('empty bars'), { step: 'fetch_bars' });
    const bars = results.map(b => ({ date: msToNyDate(b.t), open: b.o, high: b.h, low: b.l, close: b.c, t: b.t }));
    if (bars.length < 220) throw Object.assign(new Error('bar count < 220 (' + bars.length + ')'), { step: 'validate_bars' });
    const lastMs = bars.at(-1).t; const ageDays = (Date.now() - lastMs) / 86400000;
    if (ageDays > 5) throw Object.assign(new Error('freshness fail: last bar ' + bars.at(-1).date), { step: 'freshness' });
    for (const s of detect(ticker, bars)) alerts.push({ ...s, message: formatMsg(s) });
  } catch (e) {
    errors.push({ step: e.step || 'fetch_bars', error: redact(e) });
  }
}
if (errors.length) {
  return [{ json: { ok: false, runId, cfg, step: errors[0].step, error: errors[0].error, FAILURE_PREFIX, alerts: [] } }];
}
return [{ json: { ok: true, runId, cfg, alerts, FAILURE_PREFIX } }];

const prev = $('Split Alerts').all();
const slackItems = $input.all();
const cfg = $('Load Config + TZ').first().json;
const runId = $('Fetch Detect Format').first().json.runId;
const tsList = [];
for (const s of slackItems) {
  const body = s.json;
  if (body.ok !== true && body.message?.ok !== true) {
    const err = body.error || body.message?.error || 'slack_ok_false';
    return [{ json: { ok: false, runId, cfg, step: 'slack_post', error: String(err), FAILURE_PREFIX: 'STRUCTURE ALERT FAILED - ' } }];
  }
  tsList.push(body.ts || body.message?.ts || null);
}
return [{ json: { ok: true, runId, cfg, alertCount: prev.length, slackTs: tsList[0] || null } }];

const cfg = $('Load Config + TZ').first().json;
const runId = $('Fetch Detect Format').first().json.runId;
return [{ json: { ok: true, runId, cfg, alertCount: 0, slackTs: null } }];

const j = $input.first().json;
const text = `${j.FAILURE_PREFIX || 'STRUCTURE ALERT FAILED - '}${j.step}: ${j.error}`;
return [{ json: { ...j, failureText: text } }];

const base = $('Format Failure').first().json;
const slack = $input.first().json;
